	if p == nil || p.program == nil {
		return nil
	}
	if err := unix.SetsockoptInt(fd, unix.SOL_SOCKET, unix.SO_ATTACH_REUSEPORT_EBPF, p.program.FD()); err != nil {
		return fmt.Errorf("attach reuseport ebpf: %w", err)
	}
	return nil
