        policy_slug = _slugify_component(policy)
        rate_slug = _slugify_component(rate)
        link_name = results_dir / f"run-{policy_slug}-{rate_slug}"

        if link_name.exists() or link_name.is_symlink():
            try:
                if link_name.resolve() == run_path:
                    continue
            except FileNotFoundError:
                pass
            if link_name.is_symlink() or link_name.is_file():
                link_name.unlink()
            else:
                raise FileExistsError(
